'use strict';
const mongoose = require('mongoose');

// Coach-written individual progress review. Written by a coach only; never generated by AI.
// Drafts can be edited. Submitted reviews are locked.
const reviewSchema = new mongoose.Schema(
  {
    organizationId: { type: mongoose.Schema.Types.ObjectId, ref: 'Organization', required: true, index: true },
    coachId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    studentId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    status: { type: String, enum: ['draft', 'submitted'], default: 'draft' },
    strengths: { type: String, default: '', maxlength: 3000 },
    challenges: { type: String, default: '', maxlength: 3000 },
    observations: { type: String, default: '', maxlength: 3000 },
    recommendations: { type: String, default: '', maxlength: 3000 },
    nextGoals: { type: String, default: '', maxlength: 3000 },
    submittedAt: { type: Date, default: null },
  },
  { timestamps: true }
);

reviewSchema.index({ organizationId: 1, studentId: 1, createdAt: -1 });
reviewSchema.index({ organizationId: 1, coachId: 1, status: 1 });

module.exports = mongoose.model('Review', reviewSchema);
